<?php
// Features are split into modules (one file per area, see modules/). This file only loads them and routes API calls.
foreach (['core', 'landing_chat', 'google_login', 'catalog', 'keep_history', 'gw_providers', 'error_log', 'backup', 'snapshots', 'system', 'msg_templates', 'prompts', 'learning', 'learn_clean', 'guide_grow', 'case_cfg', 'case_intake', 'cmd_ai', 'lib_cmds', 'lib_texts', 'media_vault', 'staff_chat', 'bot_roles', 'client_backup', 'clients', 'business', 'cases', 'programs', 'drive', 'report', 'registry', 'bot_learning', 'bot_runner', 'bot_commands', 'learn_lean', 'suggest', 'recommend', 'case_trail', 'voice', 'bot_quality', 'team_watch', 'group_watch', 'checkin', 'case_journal', 'sys_guide', 'visitors', 'meetings', 'home', 'sharing', 'ai_activity', 'chat_tools', 'groups', 'numbers', 'legal', 'status', 'health', 'customer', 'saas_home', 'integrations'] as $wf_mod) require_once __DIR__ . '/modules/' . $wf_mod . '.php';
unset($wf_mod);
// optional add-ons (addons/<name>/addon.php): the product works the same when a folder is not there
foreach (glob(__DIR__ . '/addons/*/addon.php') ?: [] as $wf_ad) { $GLOBALS['WI_ADDONS'][basename(dirname($wf_ad))] = true; require_once $wf_ad; }
unset($wf_ad);
/** Each area handles its own API names and answers (exits); a name nobody handles returns here, as before. */
function wi_features_api(string $api): void {
    foreach (wi_filter('api_handlers', ['wf_api_home', 'wf_api_plan_usage', 'wf_api_catalog', 'wf_api_market', 'wf_api_market_ai', 'wf_api_sharing', 'wf_api_meetings', 'wf_api_ai_activity', 'wf_api_chat_tools', 'wf_api_groups', 'wf_api_numbers', 'wf_api_bot_health', 'wf_api_bot_learning', 'wf_api_bot_commands', 'wf_api_learn_lean', 'wf_api_suggest', 'wf_api_recommend', 'wf_api_case_trail', 'wf_api_bot_quality', 'wf_api_team_watch', 'wf_api_checkin', 'wf_api_case_journal', 'wf_api_system', 'wf_api_menu_cfg', 'wf_api_gw_rules', 'wf_api_msg_templates', 'wf_api_prompts', 'wf_api_learning', 'wf_api_learning_docs', 'wf_api_learn_clean', 'wf_api_guide_grow', 'wf_api_case_cfg', 'wf_api_case_intake', 'wf_api_bot_roles', 'wf_api_sysguide', 'wf_api_visitors', 'wf_api_cases', 'wf_api_status', 'wf_api_health', 'wf_api_customer', 'wf_api_programs', 'wf_api_report', 'wf_api_drive', 'wf_api_client_backup', 'wf_api_business']) as $fn) $fn($api);
}
